function renderCode(){const lesson=lessons[state.lesson],step=lesson.steps[state.step],area=$('codeArea');if(lesson.files){const names=Object.keys(lesson.files);area.classList.add('dual-code-area');area.innerHTML=Object.entries(lesson.files).map(([file,code])=>`<section class="dual-code-file ${file===step.file?'active-file':''}"><div class="dual-file-header"><span class="java-dot">J</span><strong>${file}</strong><small>${file==='App.java'?'runs the program':`defines ${file.replace('.java','')} objects`}</small></div><div class="dual-file-code">${codeLines(code,file===step.file,step)}</div></section>`).join('');$('fileName').textContent=names.join(' + ')}else{area.classList.remove('dual-code-area');const file='Main.java';$('fileName').textContent=file;area.innerHTML=codeLines(lesson.code,true,step)}document.querySelector('.code-line.active')?.scrollIntoView({block:'nearest'})}
