$('whyButton').addEventListener('click',()=>{const d=$('whyDrawer'),open=d.hidden;d.hidden=!open;$('whyButton').setAttribute('aria-expanded',String(open))});
let helpReturnFocus=null;function openHelp(){helpReturnFocus=document.activeElement;$('helpModal').hidden=false;$('closeHelp').focus()}function closeHelp(){if($('helpModal').hidden)return;$('helpModal').hidden=true;helpReturnFocus?.focus();helpReturnFocus=null}
$('helpButton').addEventListener('click',openHelp);$('closeHelp').addEventListener('click',closeHelp);$('helpModal').addEventListener('click',event=>{if(event.target===$('helpModal'))closeHelp()});
$('replayTourButton').addEventListener('click',()=>{closeHelp();startTour(true)});

const TOUR_KEY='javaJourneyWelcomeTourV1';
const tourSteps=[
  {target:null,kicker:'Welcome to Java Journey',title:'You do not need to understand every symbol yet',text:'That is completely normal. We will follow one highlighted line at a time, see what Java does, and explain the unfamiliar pieces as we need them.',button:'Show me around'},
  {target:'.code-panel',kicker:'1 · The Java code',title:'Follow the highlighted line',text:'This is the program. The amber highlight shows the line Java is dealing with now. You can ignore the other words and symbols for the moment.',button:'Next'},
  {target:'.visual-panel',kicker:'2 · What happens',title:'Watch the program come alive',text:'This side shows the effect of the highlighted code. At first it stays simple; objects, variables and arrows appear only when a lesson needs them.',button:'Next'},
  {target:'.explanation-card',kicker:'3 · Plain English',title:'Read what Java just did',text:'Each step includes a short everyday-language explanation. Use “Explain this” only when you want the deeper technical reason.',button:'Next'},
  {target:'#nextButton',kicker:'4 · Your main control',title:'Press Next step to continue',text:'That is all you need to begin. Later, you can predict outcomes, replay steps and explore other views—but start by moving one step at a time.',button:'Start learning'}
];
let tourIndex=0,tourReturnFocus=null;
function tourHasBeenSeen(){try{return localStorage.getItem(TOUR_KEY)==='done'}catch{return false}}
function positionTourCard(target){const card=$('tourCard'),spotlight=$('tourSpotlight');card.removeAttribute('style');spotlight.removeAttribute('style');if(!target)return;const rect=target.getBoundingClientRect(),gap=16,estimatedHeight=270;spotlight.style.left=`${rect.left-5}px`;spotlight.style.top=`${rect.top-5}px`;spotlight.style.width=`${rect.width+10}px`;spotlight.style.height=`${rect.height+10}px`;if(window.innerWidth>760&&rect.left>250){card.style.width=`${Math.min(300,rect.left-32)}px`;card.style.left='16px';card.style.top=`${Math.max(16,Math.min(rect.top,window.innerHeight-estimatedHeight-16))}px`;return}const cardWidth=Math.min(390,window.innerWidth-32);let left=Math.min(Math.max(16,rect.left),window.innerWidth-cardWidth-16),top=rect.bottom+gap;if(top+estimatedHeight>window.innerHeight)top=Math.max(16,rect.top-estimatedHeight-gap);card.style.left=`${left}px`;card.style.top=`${top}px`}
function renderTour(){document.querySelector('.tour-focus')?.classList.remove('tour-focus');const tour=$('lessonTour'),step=tourSteps[tourIndex],target=step.target?document.querySelector(step.target):null;tour.classList.toggle('tour-step-active',Boolean(target));if(target){target.classList.add('tour-focus');target.scrollIntoView({block:'center',behavior:'smooth'})}tour.hidden=false;$('tourKicker').textContent=step.kicker;$('tourTitle').textContent=step.title;$('tourText').textContent=step.text;$('tourProgress').textContent=`${tourIndex+1} of ${tourSteps.length}`;$('tourNextButton').textContent=step.button;$('tourSkipButton').textContent=tourIndex===0?'Skip tour':'Close';setTimeout(()=>positionTourCard(target),target?280:0);$('tourNextButton').focus()}
function startTour(force=false){if(!force&&(tourHasBeenSeen()||state.lesson!==0))return;pause();tourReturnFocus=document.activeElement;tourIndex=0;renderTour()}
function finishTour(){document.querySelector('.tour-focus')?.classList.remove('tour-focus');$('lessonTour').hidden=true;$('lessonTour').classList.remove('tour-step-active');try{localStorage.setItem(TOUR_KEY,'done')}catch{}tourReturnFocus?.focus();tourReturnFocus=null}
$('tourNextButton').addEventListener('click',()=>{if(tourIndex<tourSteps.length-1){tourIndex++;renderTour()}else finishTour()});
$('tourSkipButton').addEventListener('click',finishTour);
$('lessonTour').querySelector('.tour-shade').addEventListener('click',()=>{if(tourIndex===0)finishTour()});
window.addEventListener('resize',()=>{if(!$('lessonTour').hidden){const target=tourSteps[tourIndex].target?document.querySelector(tourSteps[tourIndex].target):null;positionTourCard(target)}});
$('resetProgressButton').addEventListener('click',()=>{localStorage.removeItem(STORAGE_KEY);pause();state.lesson=0;state.step=0;state.completed.clear();state.predictions.clear();state.view='memory';$('speedSelect').value='1000';activateView(viewTabs[0]);render();$('resetProgressButton').textContent='Progress reset'});
document.addEventListener('keydown',event=>{if(!$('lessonTour').hidden){if(event.key==='Escape'){event.preventDefault();finishTour()}return}if(!$('helpModal').hidden){if(event.key==='Escape'){event.preventDefault();closeHelp();return}if(event.key==='Tab'){const focusable=[$('closeHelp'),$('replayTourButton'),$('resetProgressButton')],current=focusable.indexOf(document.activeElement),next=event.shiftKey?(current-1+focusable.length)%focusable.length:(current+1)%focusable.length;event.preventDefault();focusable[next].focus()}return}if(['INPUT','SELECT','TEXTAREA','BUTTON','A'].includes(document.activeElement.tagName))return;if(event.code==='Space'){event.preventDefault();play()}else if(event.key==='ArrowRight')next();else if(event.key==='ArrowLeft')previous();else if(event.key.toLowerCase()==='r')reset()});
$('speedSelect').value=['1500','1000','650','400'].includes(String(savedProgress.speed))?String(savedProgress.speed):'1000';
render();
setTimeout(startTour,500);
